const SpellInfo& ScriptSession::phoenixFireInfo(std::uint32_t ability,unsigned level){
    auto key=std::pair{ability,level};if(auto found=phoenixFireInfo_.find(key);found!=phoenixFireInfo_.end())return found->second;auto& p=passiveInfo(ability,level);if(p.kind!=PassiveKind::PhoenixFire)throw std::runtime_error("Phoenix Fire requires its source passive");SpellInfo s;s.ability=ability;s.level=level;s.kind=SpellKind::PhoenixFire;s.amount=p.amount;s.secondary=p.secondary;s.area=p.area;s.cooldown=p.bonus;s.duration=p.duration;s.heroDuration=p.heroDuration;s.allowed=p.allowed;s.buff=p.buff;auto& data=definitions();s.speed=data.number(ability,"Profile","Missilespeed");s.missileArc=data.number(ability,"Profile","Missilearc");s.missile=data.field(ability,"Profile","Missileart");if(auto comma=s.missile.find(',');comma!=std::string::npos)s.missile.resize(comma);if(s.speed<0 || s.speed>100000 || !std::isfinite(s.speed) || s.missileArc<0 || s.missileArc>100 || !std::isfinite(s.missileArc))throw std::runtime_error("Invalid source Phoenix Fire projectile");return phoenixFireInfo_.emplace(key,std::move(s)).first->second;
}
void ScriptSession::refreshPhoenixFire(UnitState& u){
    if(!u.handle || !units_.contains(u.handle))return;std::map<std::uint32_t,unsigned> candidates;for(auto [ability,level]:u.abilities)if(level>0)candidates[ability]=unsigned(level);if(inventoryFlag(u,"DataC"))for(auto item:u.inventory)if(item && alive(item,NativeKind::Item) && items_.at(item)->holder==u.handle)for(auto ability:itemAbilities(items_.at(item)->type))candidates[ability]=std::max(1u,candidates[ability]);std::set<std::uint32_t> desired;if(!u.removing && !u.illusion)for(auto [ability,level]:candidates)if(passiveInfo(ability,level).kind==PassiveKind::PhoenixFire){desired.insert(ability);auto key=std::pair{u.handle,ability};phoenixFireClocks_.try_emplace(key,PhoenixFireClock{phoenixFireInfo(ability,level).cooldown});}
    std::erase_if(u.pillageBalances,[&](auto& entry){auto found=candidates.find(entry.first);return found==candidates.end() || passiveInfo(found->first,found->second).kind!=PassiveKind::Pillage;});refreshWeaponEffects(u);refreshAmbientPassives(u,candidates);for(auto it=phoenixFireClocks_.lower_bound({u.handle,0});it!=phoenixFireClocks_.end() && it->first.first==u.handle;)if(!desired.contains(it->first.second))it=phoenixFireClocks_.erase(it);else ++it;if(desired.empty())phoenixFireActors_.erase(u.handle);else phoenixFireActors_.insert(u.handle);
}
void ScriptSession::clearPhoenixBurn(std::uint32_t target,std::uint64_t ticket){auto found=phoenixBurns_.find(target);if(found==phoenixBurns_.end() || (ticket && found->second.ticket!=ticket))return;for(auto effect:found->second.visuals)destroyEffect(effect);phoenixBurns_.erase(found);}
void ScriptSession::removePhoenixFire(std::uint32_t unit){
    removeAmbientPassives(unit);clearPhoenixBurn(unit);phoenixFireActors_.erase(unit);for(auto it=phoenixFireClocks_.lower_bound({unit,0});it!=phoenixFireClocks_.end() && it->first.first==unit;)it=phoenixFireClocks_.erase(it);std::vector<std::uint32_t> targets;for(auto& [target,burn]:phoenixBurns_)if(burn.source==unit)targets.push_back(target);for(auto target:targets)clearPhoenixBurn(target);for(auto it=spellMissiles_.begin();it!=spellMissiles_.end();)if(it->second.spell.kind==SpellKind::PhoenixFire && (it->second.source==unit || it->second.target==unit))it=spellMissiles_.erase(it);else ++it;
}
void ScriptSession::phoenixFireImpact(const SpellMissile& missile){
    if(!alive(missile.source,NativeKind::Unit) || !alive(missile.target,NativeKind::Unit))return;auto from=units_.at(missile.source),to=units_.at(missile.target);auto& s=missile.spell;if(!spellTarget(*from,*to,s,false,missile.owner))return;auto deathRevision=to->deathRevision;damageUnit(missile.source,missile.target,s.amount,0,8);if(!alive(missile.source,NativeKind::Unit) || from->removing || !alive(missile.target,NativeKind::Unit) || to->removing || to->deathRevision!=deathRevision || number(to->life)<=0 || to->rebirth || !spellTarget(*from,*to,s,false,missile.owner) || phoenixBurns_.contains(missile.target))return;auto duration=to->hero?s.heroDuration:s.duration;if(duration<=0 || s.secondary<=0)return;if(phoenixBurns_.size()>=16384 || phoenixBurnTicket_==UINT64_MAX)throw std::runtime_error("Phoenix Fire burn budget exceeded");PhoenixBurn burn;burn.ability=s.ability;burn.level=s.level;burn.damagePerSecond=s.secondary;burn.born=simulationTime_;burn.source=missile.source;burn.target=missile.target;burn.owner=missile.owner;burn.ticket=++phoenixBurnTicket_;burn.remaining=duration;burn.visuals=spellVisual(s,"TargetArt",missile.target,{to->x,to->y},false);phoenixBurns_.emplace(missile.target,std::move(burn));
}
void ScriptSession::phoenixFireTick(double delta){
    std::vector<std::uint32_t> burning;for(auto& [target,burn]:phoenixBurns_)burning.push_back(target);for(auto target:burning){auto found=phoenixBurns_.find(target);if(found==phoenixBurns_.end())continue;auto source=found->second.source;auto ticket=found->second.ticket;if(!alive(target,NativeKind::Unit) || !alive(source,NativeKind::Unit) || units_.at(target)->removing || number(units_.at(target)->life)<=0){clearPhoenixBurn(target,ticket);continue;}if(units_.at(target)->paused || found->second.born>=simulationTime_)continue;auto& burn=found->second;double elapsed=std::min(delta,burn.remaining);burn.remaining-=elapsed;burn.period+=elapsed;float amount=0;while(burn.period>=1){burn.period-=1;amount+=burn.damagePerSecond;}bool expired=burn.remaining<=0;if(expired && burn.period>0)amount+=float(burn.period)*burn.damagePerSecond;if(amount>0)damageUnit(source,target,amount,0,8);if(expired)clearPhoenixBurn(target,ticket);}
    if(phoenixFireActors_.empty())return;std::set<std::uint32_t> reserved;for(auto& [id,missile]:spellMissiles_)if(missile.spell.kind==SpellKind::PhoenixFire)reserved.insert(missile.target);std::vector<std::uint32_t> actors(phoenixFireActors_.begin(),phoenixFireActors_.end());for(auto source:actors){if(!alive(source,NativeKind::Unit)){removePhoenixFire(source);continue;}auto u=units_.at(source);if(u->removing || u->illusion || u->paused || u->hidden() || u->morphed() || u->construction || number(u->life)<=0)continue;auto owner=u->owner;auto abilities=passiveAbilities(*u);for(auto [ability,level]:abilities){if(!alive(source,NativeKind::Unit) || u->removing || u->owner!=owner || u->paused || u->hidden() || u->morphed() || number(u->life)<=0)break;if(passiveInfo(ability,level).kind!=PassiveKind::PhoenixFire)continue;auto available=config_.players[owner].abilityAvailable.find(ability);if(available!=config_.players[owner].abilityAvailable.end() && !available->second)continue;auto key=std::pair{source,ability};auto clock=phoenixFireClocks_.find(key);if(clock==phoenixFireClocks_.end())continue;auto& s=phoenixFireInfo(ability,level);clock->second.remaining-=delta;if(clock->second.remaining>0)continue;auto current=passiveAbilities(*u);if(std::none_of(current.begin(),current.end(),[&](auto entry){return entry.first==ability && entry.second==level;}))continue;clock->second.remaining=std::max(double(s.cooldown),1./32);auto targets=spellTargets(source,s,{u->x,u->y},owner);std::erase_if(targets,[&](auto target){return reserved.contains(target) || phoenixBurns_.contains(target) || mechanicalDisguised(*units_.at(target),owner) || !spellTarget(*u,*units_.at(target),s,true,owner);});if(targets.empty())continue;auto target=targets[random()%targets.size()];SpellMissile missile;missile.spell=s;missile.source=source;missile.target=target;missile.owner=owner;missile.position={u->x,u->y};missile.amount=s.amount;reserved.insert(target);launchSpellMissile(std::move(missile));}
    }
}
